/* ===================================================================
   AMA can (aerosol only), the 3D half of the first-visit intro.
   Built Nov 2, 2026 from the AMA characters source (Oct 14, 2026).
   Loaded only on a first visit, with three.js r128: the 211 x 413 (the
   spotlight's 713 profile with the wall shortened), plain steel, with Don's
   TE 510 swirl cap turned so its tamper tab faces away. An orthographic
   camera frames the same box as the drawing (mm, the drawing's y flipped),
   so the 3D lands exactly on the ink.
   start(canvas, cssW, cssH, viewBox, kind, base) -> { frame({ y, ry, rx, sx, sy }), dispose(), gl } | null
   =================================================================== */
(function () {
  const AF = window.AF = window.AF || {};
  const CAN = [[0,-125.34],[8.5,-125.84],[13.6,-126.84],[17,-127.84],[19.7,-128.84],[22.2,-129.84],[24.4,-130.84],[26.3,-131.84],[30.3,-137.94],[31.4,-138.44],[32.5,-138.14],[32.83,-137.44],[32.83,-135.64],[31.6,-134.84],[32.6,-134.04],[33.27,-132.74],[33.27,-41],[33.21,-38.5],[33.04,-35.5],[32.74,-33.5],[32.32,-30.5],[31.79,-28.5],[31.14,-26.5],[30.38,-23.5],[29.5,-21.5],[28.52,-19.5],[27.42,-17.5],[26.1,-15],[24.8,-13],[23.4,-11],[21.9,-9],[20.4,-7.5],[18.8,-5.5],[17.2,-3.5],[15.6,-1.5],[15.74,0.5],[15.74,2.4],[15.1,3.35],[13.9,3.55],[12.9,3.05],[12.5,1.6],[12.5,0]], CAP_TE = {"b":[-22.5549,0.0635,-17.6734,17.6669,40.1172,17.7174],"p":"","i":"","w":2};

  const tex = (w, h, draw) => { const c = document.createElement('canvas'); c.width = w; c.height = h; draw(c.getContext('2d'), w, h); return c; };
  function studio(T) {
    const c = tex(1024, 512, (g, w, h) => {
      const room = g.createLinearGradient(0, 0, 0, h); room.addColorStop(0, '#b3babf'); room.addColorStop(.42, '#8d959b'); room.addColorStop(.5, '#646c72'); room.addColorStop(.56, '#2b3135'); room.addColorStop(1, '#1e2326');
      g.fillStyle = room; g.fillRect(0, 0, w, h);
      [[.66, 90, 1], [.84, 26, 1], [.47, 30, .6], [.02, 26, .55], [.98, 26, .55]].forEach(([u, bw, a]) => {
        const x = u * w, gr = g.createLinearGradient(x - bw, 0, x + bw, 0);
        gr.addColorStop(0, 'rgba(255,255,255,0)'); gr.addColorStop(.5, `rgba(255,255,255,${a})`); gr.addColorStop(1, 'rgba(255,255,255,0)');
        g.fillStyle = gr; g.fillRect(x - bw, h * .08, bw * 2, h * .44);
      });
      g.fillStyle = 'rgba(138,229,255,.5)'; g.fillRect(0, h * .5, w, h * .015);
    });
    const t = new T.CanvasTexture(c); t.mapping = T.EquirectangularReflectionMapping; t.encoding = T.sRGBEncoding; return t;
  }
  function bands(T, seed0, base, n, lo, span, srgb) {
    let seed = seed0; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    const c = tex(1024, 8, (g, w, h) => {
      g.fillStyle = base; g.fillRect(0, 0, w, h);
      for (let i = 0; i < n; i++) {
        const x = rnd() * w, bw = 16 + rnd() * 50, v = lo + rnd() * span | 0;
        for (const o of [-w, 0, w]) { const gr = g.createLinearGradient(x + o - bw, 0, x + o + bw, 0);
          gr.addColorStop(0, `rgba(${v},${v},${v},0)`); gr.addColorStop(.5, `rgba(${v},${v},${v},.85)`); gr.addColorStop(1, `rgba(${v},${v},${v},0)`);
          g.fillStyle = gr; g.fillRect(x + o - bw, 0, bw * 2, h); }
      }
    });
    const t = new T.CanvasTexture(c); t.wrapS = T.RepeatWrapping; if (srgb) t.encoding = T.sRGBEncoding; return t;
  }
  function meshFromRec(T, rec) {
    const bin = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
    const q = new Uint16Array(bin(rec.p).buffer), pos = new Float32Array(q.length), b = rec.b;
    for (let i = 0; i < q.length; i++) { const k = i % 3; pos[i] = b[k] + q[i] / 65535 * (b[k + 3] - b[k]); }
    const ib = bin(rec.i).buffer, idx = rec.w === 2 ? new Uint16Array(ib) : new Uint32Array(ib);
    const g = new T.BufferGeometry(); g.setAttribute('position', new T.BufferAttribute(pos, 3)); g.setIndex(new T.BufferAttribute(idx, 1)); g.computeVertexNormals();
    return g;
  }
  const lathe = (T, pts, n) => new T.LatheGeometry(pts.map(([r, y]) => new T.Vector2(Math.max(r, .001), y)), n);

  /* ---------- the packs ---------- */
  function buildCan(T, env, K, own) {
    const g = new T.Group();
    const steel = own(new T.MeshStandardMaterial({ color: 0xe9eef2, metalness: 1, roughness: 1, envMap: env, envMapIntensity: 1.25,
      roughnessMap: K ? K.grain(T) : bands(T, 7, 'rgb(60,60,60)', 16, 34, 56), map: K ? K.tone(T) : bands(T, 11, '#fff', 12, 200, 40, true) }));
    const plastic = own(new T.MeshStandardMaterial({ color: 0xf7f7f3, metalness: 0, roughness: .42, envMap: env, envMapIntensity: .95 }));
    const cap = new T.Mesh(meshFromRec(T, (AF.anatomyParts && AF.anatomyParts.capTE) || CAP_TE), plastic); cap.position.y = 1.14; cap.rotation.y = -Math.PI / 2;
    g.add(new T.Mesh(lathe(T, CAN, 120), steel), cap);
    return g;
  }
  function start(canvas, w, h, VB, kind, base) {
    const T = window.THREE; if (!T || !T.LatheGeometry || !w || !h) return null;
    let R;
    try { R = new T.WebGLRenderer({ canvas, antialias: true, alpha: true, powerPreference: 'low-power' }); } catch (e) { return null; }
    R.outputEncoding = T.sRGBEncoding; R.toneMapping = T.ACESFilmicToneMapping; R.toneMappingExposure = 1.12;
    R.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2)); R.setSize(w, h, false); R.setClearColor(0x000000, 0);
    const K = AF.can3d && AF.can3d.kit;
    const scene = new T.Scene(), pm = new T.PMREMGenerator(R), env = pm.fromEquirectangular(K ? K.studio(T) : studio(T)).texture;
    const mats = [], texs = [];
    const own = (m) => { mats.push(m); return m; }; own.tex = (t) => { texs.push(t); return t; };
    const pack = buildCan(T, env, K, own);
    scene.add(new T.HemisphereLight(0xffffff, 0x8a96a0, .35));
    const key = new T.DirectionalLight(0xffffff, .55); key.position.set(-80, 120, 160); scene.add(key);
    // squash about the base, drop, tilt about the middle, turn about the axis
    const mid = base / 2;
    const spin = new T.Group(); spin.add(pack);
    const tiltIn = new T.Group(); tiltIn.position.y = mid; tiltIn.add(spin);
    const tilt = new T.Group(); tilt.position.y = -mid; tilt.add(tiltIn);
    const drop = new T.Group(); drop.add(tilt);
    const sqIn = new T.Group(); sqIn.position.y = base; sqIn.add(drop);
    const squash = new T.Group(); squash.position.y = -base; squash.add(sqIn);
    scene.add(squash);
    // the drawing's box, 1.5 times as tall (room to drop in from above): world y = -svg y
    const bot = -(VB.y + VB.h), top = bot + h * VB.w / w;
    const cam = new T.OrthographicCamera(VB.x, VB.x + VB.w, top, bot, 1, 2000); cam.position.set(0, 0, 600); cam.lookAt(0, 0, 0); cam.updateProjectionMatrix();
    function frame(s) { spin.rotation.y = s.ry; tilt.rotation.x = s.rx; drop.position.y = s.y; squash.scale.set(s.sx, s.sy, s.sx); R.render(scene, cam); }
    function dispose() {
      scene.traverse((o) => { if (o.geometry) o.geometry.dispose(); });
      mats.forEach((m) => { ['map', 'roughnessMap'].forEach((k) => m[k] && m[k].dispose()); m.dispose(); });
      texs.forEach((t) => t.dispose()); env.dispose(); pm.dispose(); R.dispose(); try { R.forceContextLoss(); } catch (e) { /* already gone */ }
    }
    return { frame, dispose, gl: R.getContext() };
  }
  AF.amaMorph3D = { start };
})();
